def all_anagrams(typed, handwritten):
    return all(sorted(a) == sorted(b)
               for a, b in zip(typed, handwritten))

def tiles_to_discard(tiles):
    from collections import Counter
    odd = sum(1 for c in Counter(tiles).values() if c % 2)
    return max(0, odd - 1)

